scription": "Pediatric vital signs vary by age, and early deterioration can be subtle.", "children": [{"id": "297c6f6e-ba9d-4e21-acb6-1ba07d6871f6", "type": "concept", "title": "Age-based norms"}, {"id": "3d879f43-255b-4944-8578-37529a6ac3cc", "type": "concept", "title": "Work of breathing"}, {"id": "4a1f62fa-4d8c-4a42-9958-d4172ce6feeb", "type": "concept", "title": "Perfusion"}, {"id": "2f9bfe97-5af3-4d9a-849e-5ac281a2d0c1", "type": "concept", "title": "Pediatric early warning cues"}]}, {"id": "1e8f563f-2377-403a-b672-decb4f1e3a84", "type": "subtopic", "title": "Pain and comfort assessment", "description": "Pain assessment must account for age, communication ability, culture, and caregiver input.", "children": [{"id": "10240a70-29df-4938-8294-af45209d72a3", "type": "concept", "title": "FLACC"}, {"id": "6b2fbfe8-f268-4ad2-b497-dcadc71c96ab", "type": "concept", "title": "Faces scales"}, {"id": "301c3196-23f2-4567-bea7-0bbbea3d8ed9", "type": "concept", "title": "Numeric scales"}, {"id": "51353dbd-0332-4167-9fcd-c4568ec6d8e4", "type": "concept", "title": "Nonpharmacologic comfort measures"}]}]}, {"id": "d87de3f5-447a-428a-9ad6-916049706927", "type": "topic", "title": "Health Promotion, Immunizations, Nutrition, and Anticipatory Guidance", "description": "Use preventive care, vaccines, nutrition, sleep, injury prevention, and family teaching to support healthy development.", "children": [{"id": "93904111-7646-45c3-a479-bb38b60fd145", "type": "subtopic", "title": "Preventive pediatric care", "description": "Preventive care keeps the course grounded in health, not only illness.", "children": [{"id": "1329fa1d-0359-444a-b3d4-7070f3ac3ecd", "type": "concept", "title": "Well-child visits"}, {"id": "287cd206-da2c-4226-b751-34403750126f", "type": "concept", "title": "Bright Futures framework"}, {"id": "e71a820f-756f-4bd2-9370-4a76c0fb30c5", "type": "concept", "title": "Screening"}, {"id": "671e26fc-e574-44e7-af9d-39fd50f5381b", "type": "concept", "title": "Health supervision"}