  title = 'Pediatric Nursing',
  goal = 'Pediatric Nursing',
  summary = 'This course prepares nurses to care for infants, children, and adolescents through family-centered, developmentally appropriate practice. Students learn assessment, communication, health promotion, medication safety, common and complex pediatric conditions, safeguarding, equity, and reflective professional practice.',
  data = $pedjson${"slug": "pediatric-nursing", "title": "Pediatric Nursing", "description": "This course prepares nurses to care for infants, children, and adolescents through family-centered, developmentally appropriate practice. Students learn assessment, communication, health promotion, medication safety, common and complex pediatric conditions, safeguarding, equity, and reflective professional practice.", "topics": [{"id": "5c9e5182-6320-41da-98a8-c1ce3b244228", "type": "topic", "title": "Pediatric Nursing Foundations and Family-Centered Care", "description": "Frame pediatric nursing around children, families, development, advocacy, consent/assent, safety, and trauma-informed partnership.", "children": [{"id": "89932cd9-af16-4cfc-a6f8-2ec4ea33aa40", "type": "subtopic", "title": "Pediatric nursing role", "description": "This subtopic defines how pediatric nursing differs from adult care because children are developing, family-supported, and legally dependent patients.", "children": [{"id": "3880caf5-7388-4822-849a-17c86fd94b94", "type": "concept", "title": "Child- and family-centered care"}, {"id": "a905c9b1-b867-4769-bcd7-4733e4d9ffb9", "type": "concept", "title": "Developmental vulnerability"}, {"id": "a51d692e-b73d-4e96-9d56-7d98a62fa260", "type": "concept", "title": "Advocacy"}, {"id": "b5509d6f-0f1b-4ad9-b8bd-d57eb7e6cade", "type": "concept", "title": "Interprofessional practice"}]}, {"id": "2033e02a-baff-4278-88c2-fcb1e95ee58a", "type": "subtopic", "title": "Consent, assent, and ethical care", "description": "Students learn how decision-making changes when minors, parents or guardians, and clinicians all have roles.", "children": [{"id": "5aec2b3c-272b-4798-b80c-376907f80574", "type": "concept", "title": "Parental permission"}, {"id": "717d4bc0-b0d5-4821-96b2-21eeb56b8fd6", "type": "concept", "title": "Child assent"}, {"id": "103151f2-a5fb-4a93-9e0e-35fe0cd724d1", "type": "concept", "title": "Confidential adolescent care"}, {"id": "8eba5457-3146-4b49-a065-bd610c5d9cec", "type": "concept", "title": "Best-interest standard"}]}, {"id": "b6244e0e-2716-40fc-8ecc-54fa08aa9143", "type": "subtopic", "title": "Trauma-informed pediatric care", "description": "Trauma-informed care reduces fear and supports children and families during stressful encounters.", "children": [{"id": "667ce953-c58b-4f14-88bc-1a95d12c448a", "type": "concept", "title": "Predictability"}, {"id": "f44d66d4-df3e-421b-a93d-65f5623a3b86", "type": "concept", "title": "Choice and control"}, {"id": "25b92bee-56d4-480b-b65d-d32b2563d749", "type": "concept", "title": "Comfort positioning"}, {"id": "951c74bd-06d1-47c9-9a3a-ec403fab1e1a", "type": "concept", "title": "Avoiding retraumatization"}]}]}, {"id": "03552da8-cf87-45ab-b699-1264fbab233f", "type": "topic", "title": "Growth, Development, and Developmental Surveillance", "description": "Understand expected infant, child, and adolescent development and identify concerns that require follow-up.", "children": [{"id": "a4641bbb-4af3-44a7-9dea-00deb78db061", "type": "subtopic", "title": "Developmental domains", "description": "Developmental domains give nurses a structured way to understand milestones and identify concern.", "children": [{"id": "c4653fd0-b1a5-48bd-9447-52c7ad5f249c", "type": "concept", "title": "Gross motor"}, {"id": "f1fc4d64-1f6f-4099-b7a2-a032b15c0b52", "type": "concept", "title": "Fine motor"}, {"id": "2dbba335-e775-4a73-95b8-61a47c40c0a6", "type": "concept", "title": "Language"}, {"id": "e0be28ee-fd12-45c0-b939-3e4e5262d973", "type": "concept", "title": "Social-emotional development"}]}, {"id": "7c1630fb-a842-499d-929f-3d67b4d9ae26", "type": "subtopic", "title": "Age-stage expectations", "description": "Age-stage thinking helps nurses tailor care, teaching, play, procedures, and safety guidance.", "children": [{"id": "f438953e-ab5e-4654-bdda-9033972fd82f", "type": "concept", "title": "Infancy"}, {"id": "97c3d452-637b-4ccf-b0b3-a9fd4c641c45", "type": "concept", "title": "Toddlerhood and preschool"}, {"id": "9af35aca-6916-40fc-a3f4-6113d0d32cb1", "type": "concept", "title": "School age"}, {"id": "c2d4051b-072a-4fb6-8e40-f947fdad8a6c", "type": "concept", "title": "Adolescence"}]}, {"id": "d0797206-1735-4e6d-ae5f-01fa8921e9ee", "type": "subtopic", "title": "Screening and referral", "description": "Surveillance matters because early identification can change a child's developmental trajectory.", "children": [{"id": "9690c727-3836-4818-b9db-3355b094e554", "type": "concept", "title": "Developmental screening"}, {"id": "27aeafc4-d688-445a-ac20-09aa9deb18c6", "type": "concept", "title": "Autism screening awareness"}, {"id": "5c2fc0ea-369e-49b3-8b20-2f0ccced308e", "type": "concept", "title": "Early intervention"}, {"id": "d934c985-a756-41dd-9142-f5b1cd2978fa", "type": "concept", "title": "School-based supports"}]}]}, {"id": "3a904dd5-79f9-4898-8980-2a55855605f3", "type": "topic", "title": "Communication with Children, Adolescents, and Families", "description": "Build age-appropriate, culturally responsive communication skills that support assessment, teaching, and trust.", "children": [{"id": "19e6040c-986f-4136-b564-f9b5208d53d4", "type": "subtopic", "title": "Age-appropriate communication", "description": "Children communicate differently across development, so assessment and teaching must match cognitive and emotional capacity.", "children": [{"id": "13fb3f81-203d-4187-9f5d-1a79e14d7edc", "type": "concept", "title": "Play-based communication"}, {"id": "faa37230-230d-4895-999a-ff1f2be34d68", "type": "concept", "title": "Concrete explanations"}, {"id": "2647a66a-4cab-4158-ae54-ef528f010917", "type": "concept", "title": "Privacy for adolescents"}, {"id": "11415b8f-2a70-4a71-ba2e-d1ee71d92d96", "type": "concept", "title": "Teach-back"}]}, {"id": "38206509-0c94-41d0-93af-d3b5799065b3", "type": "subtopic", "title": "Family communication", "description": "Family partnership improves assessment accuracy, adherence, and safety planning.", "children": [{"id": "04ac4590-1474-4408-bc2a-b72a5e0d141c", "type": "concept", "title": "Caregiver concerns"}, {"id": "ad7df108-2c43-48aa-9c41-1f2fa5698e7e", "type": "concept", "title": "Shared decision-making"}, {"id": "aa78a57d-9ec8-4c3c-abbc-774d7a5e566e", "type": "concept", "title": "Interpreter use"}, {"id": "d0d1a21e-062e-4819-b0af-99fe9a1ef708", "type": "concept", "title": "Health literacy"}]}, {"id": "804742b7-15b4-4d7b-9c8b-2f9d60dbd9e8", "type": "subtopic", "title": "Procedural support", "description": "Procedural communication can reduce pain, fear, and resistance during care.", "children": [{"id": "1b7e7782-5dc7-463e-bf31-b605661b0cee", "type": "concept", "title": "Preparation"}, {"id": "861a9f80-f931-4014-82ee-d5965e98390c", "type": "concept", "title": "Distraction"}, {"id": "89d6ae10-53ec-40fb-9628-1194038b7ff3", "type": "concept", "title": "Comfort positioning"}, {"id": "199dcd2d-f0c2-4ce3-8c31-bb6a8572df0c", "type": "concept", "title": "Post-procedure debrief"}]}]}, {"id": "5c7d392a-84e3-4e10-a929-64ace2b964f1", "type": "topic", "title": "Pediatric Assessment, Vital Signs, Pain, and Clinical Reasoning", "description": "Develop the assessment patterns needed to recognize normal variation, subtle deterioration, and urgent pediatric risk.", "children": [{"id": "ed761bd8-59d6-43c5-815e-9e415818e8fa", "type": "subtopic", "title": "Pediatric history and physical assessment", "description": "Students learn assessment patterns that fit age, developmental stage, and family context.", "children": [{"id": "5a0a3a95-32ae-4612-a79c-8148d69630ca", "type": "concept", "title": "Birth and developmental history"}, {"id": "fd96e1c6-818c-4b6a-a84e-452d38f10b90", "type": "concept", "title": "Focused assessment"}, {"id": "7abb9781-a76b-4978-9b04-52eb5e241869", "type": "concept", "title": "Growth parameters"}, {"id": "6697e27c-fbfa-4197-8a9c-f63d459c320c", "type": "concept", "title": "Red flags"}]}, {"id": "67ebf5be-b8c5-42af-bc3a-c8b3494c7a10", "type": "subtopic", "title": "Vital signs and deterioration", "description": "Pediatric vital signs vary by age, and early deterioration can be subtle.", "children": [{"id": "297c6f6e-ba9d-4e21-acb6-1ba07d6871f6", "type": "concept", "title": "Age-based norms"}, {"id": "3d879f43-255b-4944-8578-37529a6ac3cc", "type": "concept", "title": "Work of breathing"}, {"id": "4a1f62fa-4d8c-4a42-9958-d4172ce6feeb", "type": "concept", "title": "Perfusion"}, {"id": "2f9bfe97-5af3-4d9a-849e-5ac281a2d0c1", "type": "concept", "title": "Pediatric early warning cues"}]}, {"id": "1e8f563f-2377-403a-b672-decb4f1e3a84", "type": "subtopic", "title": "Pain and comfort assessment", "description": "Pain assessment must account for age, communication ability, culture, and caregiver input.", "children": [{"id": "10240a70-29df-4938-8294-af45209d72a3", "type": "concept", "title": "FLACC"}, {"id": "6b2fbfe8-f268-4ad2-b497-dcadc71c96ab", "type": "concept", "title": "Faces scales"}, {"id": "301c3196-23f2-4567-bea7-0bbbea3d8ed9", "type": "concept", "title": "Numeric scales"}, {"id": "51353dbd-0332-4167-9fcd-c4568ec6d8e4", "type": "concept", "title": "Nonpharmacologic comfort measures"}]}]}, {"id": "d87de3f5-447a-428a-9ad6-916049706927", "type": "topic", "title": "Health Promotion, Immunizations, Nutrition, and Anticipatory Guidance", "description": "Use preventive care, vaccines, nutrition, sleep, injury prevention, and family teaching to support healthy development.", "children": [{"id": "93904111-7646-45c3-a479-bb38b60fd145", "type": "subtopic", "title": "Preventive pediatric care", "description": "Preventive care keeps the course grounded in health, not only illness.", "children": [{"id": "1329fa1d-0359-444a-b3d4-7070f3ac3ecd", "type": "concept", "title": "Well-child visits"}, {"id": "287cd206-da2c-4226-b751-34403750126f", "type": "concept", "title": "Bright Futures framework"}, {"id": "e71a820f-756f-4bd2-9370-4a76c0fb30c5", "type": "concept", "title": "Screening"}, {"id": "671e26fc-e574-44e7-af9d-39fd50f5381b", "type": "concept", "title": "Health supervision"}]}, {"id": "b769ae36-bcdd-43b9-bdf4-b00355ece7d1", "type": "subtopic", "title": "Immunizations", "description": "Students need schedule literacy and communication skills for vaccine safety, contraindications, and family questions.", "children": [{"id": "7477896c-3897-4256-988a-3c628a43ca3b", "type": "concept", "title": "Child and adolescent schedules"}, {"id": "54c40f7a-5612-40e7-8fd0-db1bda45de17", "type": "concept", "title": "Catch-up schedules"}, {"id": "df3219ff-d96e-4d94-8ef4-5f5eaacdd1a6", "type": "concept", "title": "Vaccine education"}, {"id": "8e7dc1fe-7e56-4eac-b888-29ffbdbbed2a", "type": "concept", "title": "Documentation"}]}, {"id": "e473ea96-a4b4-420f-bacc-e2d9406d64c4", "type": "subtopic", "title": "Nutrition, sleep, and injury prevention", "description": "Daily family guidance is a major pediatric nursing contribution.", "children": [{"id": "14f4fab2-da81-448a-b270-0584091851ef", "type": "concept", "title": "Breastfeeding and formula basics"}, {"id": "9300cfe6-7bb0-41e8-a5ca-9aca482125fa", "type": "concept", "title": "Childhood nutrition"}, {"id": "c936e6a5-371a-4599-8b1e-e7181553453e", "type": "concept", "title": "Safe sleep"}, {"id": "8d65bbd8-18f1-4d34-85ab-4eaa155ffdc2", "type": "concept", "title": "Car seats, helmets, and drowning prevention"}]}]}, {"id": "50e9f972-f0a6-42f1-966c-8ee3046dcf99", "type": "topic", "title": "Pediatric Medication Administration, Dosing, and Safety", "description": "Apply weight-based dosing, high-alert medication safeguards, caregiver education, and error-prevention habits.", "children": [{"id": "e7f5779d-c59d-45dd-9605-de46186336c6", "type": "subtopic", "title": "Weight-based dosing", "description": "Pediatric dosing requires exact calculations because small errors can cause major harm.", "children": [{"id": "decc7563-07b7-4fda-84e1-2a1b98ca10f6", "type": "concept", "title": "Kilogram-only weights"}, {"id": "d4da5d98-efe5-4a6d-bcf1-1bb39b6da8fc", "type": "concept", "title": "Dose range checks"}, {"id": "52d0ae